<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { api,errorText } from '../api'
import { time } from '../composables'
import type { AgentRun } from '../types'
const props=defineProps<{run:AgentRun;canOperate:boolean}>(),emit=defineEmits<{changed:[]}>()
const busy=ref(false),error=ref(''),reason=ref(''),decision=ref('APPROVED'),outcome=ref('NOT_EXECUTED'),note=ref(''),manualKey=ref(crypto.randomUUID())
const labels:Record<string,string>={PENDING:'等待审阅',APPROVED:'已批准线下处理',REJECTED:'已拒绝',EXPIRED:'已过期',EXECUTED:'已执行',NOT_EXECUTED:'未执行',FAILED:'执行失败'}
const expired=computed(()=>!!props.run.approval&&Date.parse(props.run.approval.expiresAt)<=Date.now())
watch([outcome,note],()=>{manualKey.value=crypto.randomUUID()})
async function submitDecision(){const approval=props.run.approval;if(!approval)return;busy.value=true;error.value='';try{await api('/agent-runs/'+props.run.id+'/approval',{method:'POST',body:{approvalRequestId:approval.id,version:approval.version,decision:decision.value,reason:reason.value}});reason.value='';emit('changed')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function submitReport(){busy.value=true;error.value='';try{await api('/agent-runs/'+props.run.id+'/manual-action-report',{method:'POST',key:manualKey.value,body:{outcome:outcome.value,note:note.value}});emit('changed')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><section v-if="run.approval" class="panel review-panel" aria-labelledby="review-heading"><div class="review-heading"><h2 id="review-heading">人工审阅</h2><strong>{{ labels[run.approval.status] }}</strong></div><p>证据与报告已冻结。批准表示允许你在线下处理，平台不会自动执行建议。</p><dl><div><dt>审阅时限</dt><dd>{{ time(run.approval.expiresAt) }}</dd></div><div><dt>报告指纹</dt><dd class="mono hash" :title="run.approval.outputHash">{{ run.approval.outputHash }}</dd></div></dl><div v-if="error" class="error-message" role="alert">{{ error }}<button class="text-button" :disabled="busy" @click="emit('changed')">刷新最新状态</button></div><template v-if="run.approval.status==='PENDING'"><p v-if="expired" class="notice">已超过审阅时限，等待服务端确认取消；本页不再接受批准。</p><form v-else-if="canOperate" @submit.prevent="submitDecision"><label>审阅决定<select v-model="decision" :disabled="busy"><option value="APPROVED">批准线下处理</option><option value="REJECTED">拒绝建议</option></select></label><label>审阅理由<textarea v-model="reason" required maxlength="2000" rows="3" :disabled="busy" placeholder="说明核对了哪些证据，以及批准或拒绝的原因"></textarea></label><button class="btn primary" :disabled="busy||!reason.trim()">{{ busy?'提交中…':'提交审阅决定' }}</button></form><p v-else class="notice">审阅需要值班角色及该目标的操作授权。</p></template><template v-else><p v-if="run.approval.reason" class="preserve-text">审阅理由：{{ run.approval.reason }}</p><p v-if="run.status==='WAITING_HUMAN'" class="notice">决定已记录，正在同步诊断断点。无需重复提交。</p><p v-if="run.approval.status==='REJECTED'" class="muted">建议已拒绝，不进入线下处理回填。</p><p v-if="run.approval.status==='EXPIRED'" class="muted">审阅已过期。需要诊断时，请从事故详情发起新任务。</p></template><template v-if="run.status==='APPROVED_FOR_MANUAL'"><h3>线下处理结果</h3><p>完成你自己的线下处理后如实回填。此操作不会改变事故状态。</p><form v-if="canOperate" @submit.prevent="submitReport"><label>实际结果<select v-model="outcome" :disabled="busy"><option value="NOT_EXECUTED">未执行</option><option value="EXECUTED">已执行</option><option value="FAILED">执行失败</option></select></label><label>处理说明<textarea v-model="note" required maxlength="2000" rows="3" :disabled="busy" placeholder="说明实际操作、未执行原因或失败情况"></textarea></label><button class="btn primary" :disabled="busy||!note.trim()">{{ busy?'保存中…':'保存线下处理结果' }}</button></form><p v-else class="notice">回填需要值班角色及该目标的操作授权。</p></template><div v-if="run.manualReport" class="manual-result"><h3>线下处理已回填：{{ labels[run.manualReport.outcome] }}</h3><p class="preserve-text">{{ run.manualReport.note }}</p><small class="muted">{{ time(run.manualReport.reportedAt) }} · 事故按原流程继续处理</small></div></section></template>
<style scoped>.review-panel{padding:24px;margin-bottom:24px;min-width:0}.review-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.review-heading strong{color:var(--accent);font-size:13px}.review-panel p{margin:12px 0}.review-panel dl{display:grid;grid-template-columns:1fr 2fr;gap:20px;margin:20px 0}.review-panel dt{font-size:12px;color:var(--muted);margin-bottom:6px}.review-panel dd{margin:0}.hash{font-size:12px;overflow-wrap:anywhere}.review-panel form{display:grid;gap:16px;max-width:680px}.review-panel form button{justify-self:start}.review-panel h3{margin:28px 0 12px}.manual-result{border-top:1px solid var(--border);margin-top:24px}@media(max-width:600px){.review-panel{padding:18px}.review-panel dl{grid-template-columns:1fr;gap:12px}}</style>
